package config

import (
	"encoding/json"

	"github.com/invopop/jsonschema"
)

const schemaBase = "https://github.com/BrutalSystems/dray/blob/v2/schema/"

// RepoConfigSchema builds the JSON Schema for .dray/config.yaml. commentsDir
// is this package's source directory, whose doc comments become descriptions;
// pass "" to leave them out. The published copies live in /schema and are
// regenerated by this package's tests.
func RepoConfigSchema(commentsDir string) ([]byte, error) {
	return schemaFor(&RepoConfig{}, commentsDir, "config.schema.json", "Dray repo config (.dray/config.yaml)")
}

// RegistryEntrySchema builds the JSON Schema for a registry entry.
func RegistryEntrySchema(commentsDir string) ([]byte, error) {
	return schemaFor(&RegistryEntry{}, commentsDir, "registry.schema.json", "Dray registry entry")
}

func schemaFor(v any, commentsDir, file, title string) ([]byte, error) {
	r := &jsonschema.Reflector{ExpandedStruct: true}
	if commentsDir != "" {
		if err := r.AddGoComments("github.com/BrutalSystems/dray/internal/config", commentsDir); err != nil {
			return nil, err
		}
	}
	s := r.Reflect(v)
	s.ID = jsonschema.ID(schemaBase + file)
	s.Title = title
	out, err := json.MarshalIndent(s, "", "  ")
	if err != nil {
		return nil, err
	}
	return append(out, '\n'), nil
}
